public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int a = sc.nextInt();
    int[] t = new int[n];
    for (int i = 0; i < n; i++) {
        t[i] = sc.nextInt();
    }
    int current_time = 0;
    for (int i = 0; i < n; i++) {
        int start_time = Math.max(t[i], current_time);
        int finish_time = start_time + a;
        current_time = finish_time;
        System.out.println(finish_time);
    }
}
